<?php
require_once __DIR__ . '/../config/auth.php';
requireRole('admin');
$pageTitle='Reports';$base='/ams';
$summary=db()->query("SELECT status,COUNT(*) total FROM attendance GROUP BY status")->fetchAll();$tot=['Present'=>0,'Late'=>0,'Absent'=>0];foreach($summary as $s)$tot[$s['status']]=(int)$s['total'];$all=array_sum($tot);$presentRate=$all?round($tot['Present']/$all*100):0;
$studentStats=db()->query("SELECT u.full_name,u.student_no,SUM(a.status='Present') present,SUM(a.status='Late') late,SUM(a.status='Absent') absent,COUNT(a.id) total FROM users u LEFT JOIN attendance a ON a.student_id=u.id WHERE u.role='student' GROUP BY u.id ORDER BY u.full_name")->fetchAll();
require __DIR__.'/../includes/header.php'; ?>
<section class="stats-grid"><div class="stat-card"><span>Present</span><strong><?= $tot['Present'] ?></strong><small>Total present records</small></div><div class="stat-card"><span>Late</span><strong><?= $tot['Late'] ?></strong><small>Total late records</small></div><div class="stat-card"><span>Absent</span><strong><?= $tot['Absent'] ?></strong><small>Total absent records</small></div><div class="stat-card"><span>Overall Rate</span><strong><?= $presentRate ?>%</strong><small>Present ÷ all records</small></div></section><div class="panel"><div class="panel-head"><div><h2>Student attendance summary</h2><p>Use this table as your printable/report-ready view.</p></div><button class="btn btn-outline btn-sm" onclick="window.print()">Print report</button></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Present</th><th>Late</th><th>Absent</th><th>Total</th><th>Rate</th></tr></thead><tbody><?php foreach($studentStats as $r): $rate=$r['total']?round($r['present']/$r['total']*100):0; ?><tr><td><strong><?= e($r['full_name']) ?></strong><small class="table-sub"><?= e($r['student_no']) ?></small></td><td><?= (int)$r['present'] ?></td><td><?= (int)$r['late'] ?></td><td><?= (int)$r['absent'] ?></td><td><?= (int)$r['total'] ?></td><td><strong><?= $rate ?>%</strong></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php require __DIR__.'/../includes/footer.php'; ?>
